// Simple endless runner for <canvas id="game"></canvas>
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = canvas.width = canvas.clientWidth || 800;
  const H = canvas.height = canvas.clientHeight || 400;

  // Game constants
  const GRAVITY = 0.6;
  const JUMP_VEL = -12;
  const PLAYER_SIZE = 20;
  const SCROLL_SPEED = 4;
  const OBSTACLE_FREQ = 120; // frames

  let frame = 0, score = 0, gameOver = false;

  const player = {
    x: 50,
    y: H - PLAYER_SIZE,
    vy: 0,
    width: PLAYER_SIZE,
    height: PLAYER_SIZE,
    sliding: false,
    jump() { if (this.onGround()) this.vy = JUMP_VEL; },
    slide(val) { this.sliding = val; },
    onGround() { return this.y >= H - this.height; },
    update() {
      this.vy += GRAVITY;
      this.y += this.vy;
      if (this.y > H - this.height) { this.y = H - this.height; this.vy = 0; }
      // slide reduces height
      this.height = this.sliding ? PLAYER_SIZE / 2 : PLAYER_SIZE;
    },
    draw() {
      ctx.fillStyle = '#0ff';
      ctx.fillRect(this.x, this.y, this.width, this.height);
    }
  };

  const obstacles = [];
  function spawnObstacle() {
    const types = ['spike', 'gap'];
    const type = types[Math.floor(Math.random() * types.length)];
    if (type === 'spike') {
      const size = 20 + Math.random() * 20;
      obstacles.push({ x: W, y: H - size, w: size, h: size, type: 'spike' });
    } else {
      const gapWidth = 40 + Math.random() * 40;
      obstacles.push({ x: W + gapWidth, y: H, w: gapWidth, h: H, type: 'gap' });
    }
  }

  function updateObstacles() {
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= SCROLL_SPEED;
      // remove off‑screen
      if (o.x + o.w < 0) obstacles.splice(i, 1);
    }
    if (frame % OBSTACLE_FREQ === 0) spawnObstacle();
  }

  function drawObstacles() {
    ctx.fillStyle = '#f00';
    obstacles.forEach(o => {
      if (o.type === 'spike') ctx.fillRect(o.x, o.y, o.w, o.h);
      // gap is just empty space, nothing to draw
    });
  }

  function checkCollision() {
    for (const o of obstacles) {
      if (o.type === 'spike') {
        if (player.x < o.x + o.w && player.x + player.width > o.x &&
            player.y < o.y + o.h && player.y + player.height > o.y) {
          return true;
        }
      } else if (o.type === 'gap') {
        // gap triggers if player steps into its horizontal range and is on ground
        if (player.x < o.x + o.w && player.x + player.width > o.x && player.onGround()) {
          return true;
        }
      }
    }
    return false;
  }

  function loop() {
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0,0,W,H);
      ctx.fillStyle = '#fff';
      ctx.font = '30px sans-serif';
      ctx.fillText('Game Over', W/2-80, H/2);
      ctx.fillText('Score: '+score, W/2-70, H/2+40);
      return;
    }
    ctx.clearRect(0,0,W,H);
    player.update();
    updateObstacles();
    player.draw();
    drawObstacles();
    if (checkCollision()) gameOver = true;
    score = Math.floor(frame / 10);
    ctx.fillStyle = '#000';
    ctx.fillText('Score: '+score, 10, 30);
    frame++;
    requestAnimationFrame(loop);
  }

  // Input handling
  window.addEventListener('keydown', e => {
    if (e.code === 'Space') player.jump();
    if (e.code === 'ArrowDown') player.slide(true);
  });
  window.addEventListener('keyup', e => {
    if (e.code === 'ArrowDown') player.slide(false);
  });

  loop();
})();

